window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c942ac845a7f834e"]={"versions": [{"id": "FIG-c942ac845a7f834e", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Artefakt-Diagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert die hierarchische Kompositionsbeziehung („Uploadable Design Artifacts“) von Konfigurations- und Entwurfsartefakten, die für die Bereitstellung auf einer Machine vorgesehen sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Uploadable Design Artifacts</strong>: Übergeordneter Container / Paketierungsartefakt, symbolisiert durch einen Briefumschlag mit seitlichen Reißverschluss-/Bindungsstrichen.\n</li><li><strong>Process Design</strong>: Dokumenten-Artefakt zur Prozessdefinition/Prozesskonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..*</code>.\n</li><li><strong>Machine Design</strong>: Dokumenten-Artefakt zur Definition der Machine-Eigenschaften/Hardware-/Netzwerkkonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..1</code>.\n</li><li><strong>Schnittstellen / Relationen</strong>: Beide Relationen nutzen UML-Schachtelungs-/Aggregationsrauten (<code>«nesting»</code>) am übergeordneten Container <code>Uploadable Design Artifacts</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Verhaltenssemantik. Zeigt die zulässige Zusammensetzung von Design-Artefakten zum Zeitpunkt des Uploads bzw. Deployments auf eine Ziel-Machine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die minimale und maximale Kardinalität der Design-Artefakte für ein auf die Machine ladbares Paket: Beliebig viele (<code>0..*</code>) <code>Process Design</code>-Artefakte und höchstens ein (<code>0..1</code>) <code>Machine Design</code>-Artefakt sind innerhalb von <code>Uploadable Design Artifacts</code> zulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9286719c94d29b90", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Artefakt-Diagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert die hierarchische Kompositionsbeziehung („Uploadable Design Artifacts“) von Konfigurations- und Entwurfsartefakten, die für die Bereitstellung auf einer Machine vorgesehen sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Uploadable Design Artifacts</strong>: Übergeordneter Container / Paketierungsartefakt, symbolisiert durch einen Briefumschlag mit seitlichen Reißverschluss-/Bindungsstrichen.\n</li><li><strong>Process Design</strong>: Dokumenten-Artefakt zur Prozessdefinition/Prozesskonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..*</code>.\n</li><li><strong>Machine Design</strong>: Dokumenten-Artefakt zur Definition der Machine-Eigenschaften/Hardware-/Netzwerkkonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..1</code>.\n</li><li><strong>Schnittstellen / Relationen</strong>: Beide Relationen nutzen UML-Schachtelungs-/Aggregationsrauten (<code>«nesting»</code>) am übergeordneten Container <code>Uploadable Design Artifacts</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Verhaltenssemantik. Zeigt die zulässige Zusammensetzung von Design-Artefakten zum Zeitpunkt des Uploads bzw. Deployments auf eine Ziel-Machine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die minimale und maximale Kardinalität der Design-Artefakte für ein auf die Machine ladbares Paket: Beliebig viele (<code>0..*</code>) <code>Process Design</code>-Artefakte und höchstens ein (<code>0..1</code>) <code>Machine Design</code>-Artefakt sind innerhalb von <code>Uploadable Design Artifacts</code> zulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d99ffc2af52a96d2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Artefakt-Diagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert die hierarchische Kompositionsbeziehung („Uploadable Design Artifacts“) von Konfigurations- und Entwurfsartefakten, die für die Bereitstellung auf einer Machine vorgesehen sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Uploadable Design Artifacts</strong>: Übergeordneter Container / Paketierungsartefakt, symbolisiert durch einen Briefumschlag mit seitlichen Reißverschluss-/Bindungsstrichen.\n</li><li><strong>Process Design</strong>: Dokumenten-Artefakt zur Prozessdefinition/Prozesskonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..*</code>.\n</li><li><strong>Machine Design</strong>: Dokumenten-Artefakt zur Definition der Machine-Eigenschaften/Hardware-/Netzwerkkonfiguration, aggregiert via Komposition/Nesting (<code>«nesting»</code>) mit Multiplizität <code>0..1</code>.\n</li><li><strong>Schnittstellen / Relationen</strong>: Beide Relationen nutzen UML-Schachtelungs-/Aggregationsrauten (<code>«nesting»</code>) am übergeordneten Container <code>Uploadable Design Artifacts</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Verhaltenssemantik. Zeigt die zulässige Zusammensetzung von Design-Artefakten zum Zeitpunkt des Uploads bzw. Deployments auf eine Ziel-Machine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die minimale und maximale Kardinalität der Design-Artefakte für ein auf die Machine ladbares Paket: Beliebig viele (<code>0..*</code>) <code>Process Design</code>-Artefakte und höchstens ein (<code>0..1</code>) <code>Machine Design</code>-Artefakt sind innerhalb von <code>Uploadable Design Artifacts</code> zulässig.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c942ac845a7f834e", "to": "FIG-9286719c94d29b90", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Linke Relation (<code>Process Design</code>): Der Stereotyp <code>«nesting»</code> wurde nach links außen verschoben (vorher auf der Verbindungslinie liegend).\n</li><li>Rechte Relation (<code>Machine Design</code>): Der Stereotyp <code>«nesting»</code> wurde leicht nach links eingerückt.\n</li></ul>"}, {"from": "FIG-9286719c94d29b90", "to": "FIG-d99ffc2af52a96d2", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
